<w:style w:type="paragraph" w:customStyle="1" w:styleId="TOAHead"><w:name w:val="TOAHead"/><w:basedOn w:val="Normal"/><w:next w:val="TOAEntry"/><w:qFormat/><w:pPr><w:keepNext/><w:spacing w:before="200" w:after="0" w:line="445" w:lineRule="exact"/><w:ind w:firstLine="0"/></w:pPr><w:rPr><w:b/><w:bCs/></w:rPr></w:style>
<w:style w:type="paragraph" w:customStyle="1" w:styleId="TOAEntry"><w:name w:val="TOAEntry"/><w:basedOn w:val="Normal"/><w:qFormat/><w:pPr><w:spacing w:before="0" w:after="0" w:line="445" w:lineRule="exact"/><w:ind w:left="720" w:hanging="720" w:firstLine="0"/></w:pPr></w:style>
