<w:style w:type="paragraph" w:styleId="TOC3"><w:name w:val="toc 3"/><w:basedOn w:val="Normal"/><w:next w:val="Normal"/><w:uiPriority w:val="39"/><w:unhideWhenUsed/><w:pPr><w:spacing w:before="0" w:after="0" w:line="445" w:lineRule="exact"/><w:ind w:left="1440" w:firstLine="0"/></w:pPr></w:style>
